Replace the conditional block by storing command objects in a map (Command pattern) and calling them polymorphically.
```rust
pub trait Command {
    fn execute(&self, data: RequestData) -> Response;
}

struct CatalogApp {
    commands: HashMap<String, Box<dyn Command>>,
}

impl CatalogApp {
    pub fn handle_request(&self, req: Request) -> Response {
        if let Some(cmd) = self.commands.get(&req.action) {
            cmd.execute(req.data)
        } else {
            Response::error(404)
        }
    }
}
